//! The privmsg messenger as a library for the phone apps.
//!
//! The same messenger as the desktop (`privmsg-node`, MLS over the Nym
//! mixnet, Tor in front), so phones and computers talk to each other. It
//! runs inside the app: there is no server. The app sees a small API,
//! [`Messenger`], with Swift bindings generated by UniFFI
//! (`scripts/build-ios.sh`).
//!
//! A `Messenger` owns a thread with the messenger's loop on it
//! (`actor.rs`). Reading (contacts, messages, settings) comes from a copy
//! the loop keeps up to date, so it never waits; doing (send, invite, …) is
//! a command to the loop, awaited from Swift with `async`. The loop reports
//! back through the app's [`Listener`]: connection status, "something
//! changed, read again", and short notices for the user.
//!
//! The profile's device key is sealed by the app's [`KeyVault`] — on the
//! iPhone, with a key in the Secure Enclave — so erasing the identity
//! ([`Messenger::erase_identity`]) can destroy it where no copy survives.

use std::path::PathBuf;
use std::sync::{Arc, Mutex, Once};
use std::time::Duration;

use anyhow::anyhow;
use privmsg_node::app::{Node, TIMERS};
use privmsg_node::secure::harden_process;
use privmsg_node::store::{shred_dir, Profile, Settings, Vault, MIN_PASSPHRASE};
use privmsg_node::wire::Invite;
use privmsg_transport::{DataMode, NymNetwork, Tor};
use tokio::sync::mpsc::{unbounded_channel, UnboundedSender};
use tokio::sync::oneshot;
use zeroize::Zeroizing;

mod actor;
mod view;

use actor::{Command, Shared};
use view::View;

uniffi::setup_scaffolding!();

/// Stack for the messenger's threads. The mixnet client's futures are
/// large (several MB unoptimised), more than the 2 MB a thread gets by
/// default; the desktop runs them on the 8 MB main thread.
const STACK_SIZE: usize = 8 << 20;

/// Default log filter, as on the desktop: warnings, minus Nym's routine
/// noise on disconnect. Logs go to stderr (Xcode's console), never a file.
const DEFAULT_LOG: &str =
    "warn,privmsg=info,nym_gateway_client::packet_router=error,nym_gateway_client::traits=off";

#[derive(Debug, uniffi::Error)]
pub enum MobileError {
    /// Something didn't work; `message` says what, in words for the user.
    Failed { message: String },
}

impl std::fmt::Display for MobileError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            MobileError::Failed { message } => f.write_str(message),
        }
    }
}

impl std::error::Error for MobileError {}

impl From<uniffi::UnexpectedUniFFICallbackError> for MobileError {
    fn from(e: uniffi::UnexpectedUniFFICallbackError) -> Self {
        MobileError::Failed { message: e.reason }
    }
}

impl From<anyhow::Error> for MobileError {
    fn from(e: anyhow::Error) -> Self {
        MobileError::Failed {
            message: format!("{e:#}"),
        }
    }
}

fn stopped() -> MobileError {
    MobileError::Failed {
        message: "privmsg has stopped. Close the app and open it again.".into(),
    }
}

#[derive(Clone, Debug, PartialEq, uniffi::Record)]
pub struct ContactInfo {
    /// What to pass back to identify the contact.
    pub name: String,
    /// `name`, safe to show.
    pub display_name: String,
    pub unread: u32,
    pub last_text: Option<String>,
    pub last_outgoing: bool,
    /// Unix seconds.
    pub last_at: Option<u64>,
    /// Disappearing messages: seconds, or none.
    pub disappear_after: Option<u64>,
    /// The same in words ("off", "1 hour").
    pub disappear_label: String,
    /// They emptied the chat for both of you since you last emptied it.
    pub cleared_by_them: bool,
}

#[derive(Clone, Debug, PartialEq, uniffi::Record)]
pub struct MessageInfo {
    /// What to pass back to delete it.
    pub id: String,
    pub outgoing: bool,
    /// Safe to show (see `view::text`).
    pub text: String,
    /// Unix seconds.
    pub at: u64,
    /// Ours, and new enough that the contact knows it by `id` too.
    pub can_delete_for_everyone: bool,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, uniffi::Enum)]
pub enum DataModeChoice {
    Saver,
    Balanced,
    Maximum,
}

impl From<DataMode> for DataModeChoice {
    fn from(mode: DataMode) -> Self {
        match mode {
            DataMode::Saver => DataModeChoice::Saver,
            DataMode::Balanced => DataModeChoice::Balanced,
            DataMode::Maximum => DataModeChoice::Maximum,
        }
    }
}

impl From<DataModeChoice> for DataMode {
    fn from(mode: DataModeChoice) -> Self {
        match mode {
            DataModeChoice::Saver => DataMode::Saver,
            DataModeChoice::Balanced => DataMode::Balanced,
            DataModeChoice::Maximum => DataMode::Maximum,
        }
    }
}

#[derive(Clone, Debug, PartialEq, uniffi::Record)]
pub struct SettingsInfo {
    /// Takes effect the next time the app starts.
    pub data_mode: DataModeChoice,
    /// Takes effect the next time the app starts.
    pub tor: bool,
    pub decoys: bool,
    /// Rest after this many idle minutes, or never.
    pub auto_sleep_minutes: Option<u32>,
}

#[derive(Clone, Debug, Default, PartialEq, uniffi::Enum)]
pub enum ConnectionStatus {
    StartingTor {
        percent: u8,
    },
    #[default]
    Connecting,
    Online,
    /// Auto-sleep: still receiving, the sender is off until needed.
    Resting,
    /// Not connected; tries again by itself in `retry_in_secs`.
    Offline {
        reason: String,
        retry_in_secs: u32,
    },
    Stopped,
}

#[derive(Clone, Debug, PartialEq, uniffi::Record)]
pub struct TimerChoice {
    /// None means off.
    pub seconds: Option<u64>,
    pub label: String,
}

/// How the app hears from the messenger. Called on the messenger's own
/// threads: hop to the main thread before touching the UI.
#[uniffi::export(with_foreign)]
pub trait Listener: Send + Sync {
    fn status(&self, status: ConnectionStatus);
    /// Contacts, messages or settings changed: read them again.
    fn changed(&self);
    /// Something to tell the user ("Alice joined. Say hi!").
    fn notice(&self, text: String);
}

/// Guards the profile's device key: the app implements it with a key that
/// lives in the Secure Enclave. What `seal` returns is stored in the
/// profile; after `destroy`, nothing sealed may ever be opened again.
#[uniffi::export(with_foreign)]
pub trait KeyVault: Send + Sync {
    fn seal(&self, key: Vec<u8>) -> Result<Vec<u8>, MobileError>;
    fn unseal(&self, sealed: Vec<u8>) -> Result<Vec<u8>, MobileError>;
    fn destroy(&self) -> Result<(), MobileError>;
}

/// The app's [`KeyVault`] as the profile's [`Vault`].
struct AppVault(Arc<dyn KeyVault>);

impl Vault for AppVault {
    fn seal(&self, key: &[u8]) -> anyhow::Result<Vec<u8>> {
        Ok(self.0.seal(key.to_vec())?)
    }

    fn unseal(&self, sealed: &[u8]) -> anyhow::Result<Zeroizing<Vec<u8>>> {
        Ok(Zeroizing::new(self.0.unseal(sealed.to_vec())?))
    }

    fn destroy(&self) -> anyhow::Result<()> {
        Ok(self.0.destroy()?)
    }
}

/// Whether `dir` holds a profile (open it) or not (create one). Finishes
/// an erase that was cut short first, and clears what an erase leaves
/// behind while the app is still running (Tor's folder).
#[uniffi::export]
pub fn profile_exists(dir: String, vault: Arc<dyn KeyVault>) -> bool {
    let dir = PathBuf::from(dir);
    if let Err(e) = Profile::finish_erase(&dir, &AppVault(vault)) {
        tracing::warn!("finishing an erase: {e:#}");
    }
    let exists = Profile::exists(&dir);
    if !exists {
        if let Err(e) = shred_dir(&dir.join("tor")) {
            tracing::warn!("clearing Tor's old folder: {e:#}");
        }
    }
    exists
}

/// Shortest passphrase a new profile accepts.
#[uniffi::export]
pub fn min_passphrase_length() -> u32 {
    MIN_PASSPHRASE as u32
}

/// The disappearing-message timers to offer, off first.
#[uniffi::export]
pub fn timer_choices() -> Vec<TimerChoice> {
    std::iter::once(None)
        .chain(TIMERS.iter().map(|(secs, _)| Some(*secs)))
        .map(|seconds| TimerChoice {
            seconds,
            label: privmsg_node::app::describe_timer(seconds),
        })
        .collect()
}

/// About how much data a data mode uses while the app is open, in MB per
/// hour (for one conversation).
#[uniffi::export]
pub fn data_mode_mb_per_hour(mode: DataModeChoice) -> u32 {
    DataMode::from(mode).mb_per_hour()
}

/// Whether `text` is an invite code (so a paste can be recognised).
#[uniffi::export]
pub fn is_invite_code(text: String) -> bool {
    Invite::from_code(text.trim()).is_ok()
}

#[derive(uniffi::Object)]
pub struct Messenger {
    commands: UnboundedSender<Command>,
    shared: Arc<Shared>,
}

#[uniffi::export]
impl Messenger {
    /// Make a new profile in `dir`, locked with `passphrase` and with its
    /// device key sealed by `vault`, and start.
    #[uniffi::constructor]
    pub fn create(
        dir: String,
        passphrase: String,
        vault: Arc<dyn KeyVault>,
        listener: Arc<dyn Listener>,
    ) -> Result<Arc<Self>, MobileError> {
        let passphrase = Zeroizing::new(passphrase);
        if passphrase.chars().count() < MIN_PASSPHRASE {
            return Err(anyhow!("Use at least {MIN_PASSPHRASE} characters.").into());
        }
        let vault = Arc::new(AppVault(vault));
        Self::start(dir.into(), passphrase, true, vault, listener, nym)
    }

    /// Unlock the profile in `dir` and start. Takes a moment: the
    /// passphrase is deliberately slow to check.
    #[uniffi::constructor]
    pub fn open(
        dir: String,
        passphrase: String,
        vault: Arc<dyn KeyVault>,
        listener: Arc<dyn Listener>,
    ) -> Result<Arc<Self>, MobileError> {
        let vault = Arc::new(AppVault(vault));
        Self::start(
            dir.into(),
            Zeroizing::new(passphrase),
            false,
            vault,
            listener,
            nym,
        )
    }

    pub fn status(&self) -> ConnectionStatus {
        self.view().status.clone()
    }

    /// Conversations, most recent first.
    pub fn contacts(&self) -> Vec<ContactInfo> {
        self.view().contacts.clone()
    }

    /// The conversation with `name`, oldest first.
    pub fn messages(&self, name: String) -> Vec<MessageInfo> {
        self.view().messages.get(&name).cloned().unwrap_or_default()
    }

    /// Names of invites not used yet.
    pub fn invites(&self) -> Vec<String> {
        self.view().invites.clone()
    }

    pub fn settings(&self) -> SettingsInfo {
        self.view().settings.clone()
    }

    /// Messages waiting for their decoy slot (decoys on).
    pub fn queued(&self) -> u32 {
        self.view().queued
    }

    /// A one-time invite code; whoever uses it becomes the contact `name`.
    pub async fn create_invite(&self, name: String) -> Result<String, MobileError> {
        self.ask(|reply| Command::Invite(name, reply)).await
    }

    /// Use someone's invite code and save them as `name`.
    pub async fn accept_invite(&self, code: String, name: String) -> Result<(), MobileError> {
        self.ask(|reply| Command::Accept { code, name, reply })
            .await
    }

    /// Send `text` to `name`. With decoys on it is queued for the next
    /// decoy slot and this returns at once.
    pub async fn send(&self, name: String, text: String) -> Result<(), MobileError> {
        self.ask(|reply| Command::Send { name, text, reply }).await
    }

    /// Disappearing messages for the chat with `name`, on both sides.
    pub async fn set_timer(&self, name: String, after: Option<u64>) -> Result<(), MobileError> {
        self.ask(|reply| Command::SetTimer { name, after, reply })
            .await
    }

    /// Delete the message `id` from the chat with `name`: here only, or
    /// (for a message we sent) on both sides.
    pub async fn delete_message(
        &self,
        name: String,
        id: String,
        everyone: bool,
    ) -> Result<(), MobileError> {
        let id = view::parse_id(&id)?;
        self.ask(|reply| Command::Delete {
            name,
            id,
            everyone,
            reply,
        })
        .await
    }

    /// Empty the chat with `name` (the contact stays): here only, or on
    /// both sides.
    pub async fn clear_chat(&self, name: String, everyone: bool) -> Result<(), MobileError> {
        self.ask(|reply| Command::Clear {
            name,
            everyone,
            reply,
        })
        .await
    }

    /// Forget a contact (or an unused invite) and destroy its addresses.
    pub async fn remove(&self, name: String) -> Result<(), MobileError> {
        self.ask(|reply| Command::Remove(name, reply)).await
    }

    /// Give `name` a new address to write to.
    pub async fn rotate(&self, name: String) -> Result<(), MobileError> {
        self.ask(|reply| Command::Rotate(name, reply)).await
    }

    /// The conversation's safety number, to compare in person.
    pub async fn safety_number(&self, name: String) -> Result<String, MobileError> {
        self.ask(|reply| Command::SafetyNumber(name, reply)).await
    }

    /// The user has seen the chat with `name`.
    pub fn mark_read(&self, name: String) {
        self.tell(Command::MarkRead(name));
    }

    pub async fn set_settings(&self, settings: SettingsInfo) -> Result<(), MobileError> {
        let settings = Settings {
            data_mode: settings.data_mode.into(),
            tor: settings.tor,
            decoy_interval: settings.decoys.then_some(actor::DEFAULT_DECOY_INTERVAL),
            auto_sleep: settings.auto_sleep_minutes.filter(|m| *m > 0),
        };
        self.ask(|reply| Command::SetSettings(settings, reply))
            .await
    }

    /// Erase the identity for good: every message, contact and key on this
    /// phone, and the device key, so no leftover copy can ever be opened.
    /// With `tell_contacts`, first ask every contact's app to delete the
    /// chat and forget us. Refused (nothing happens) unless `passphrase` is
    /// right; after a few wrong ones each try has to wait. On success the
    /// messenger stops; returns a note on how telling the contacts went.
    pub async fn erase_identity(
        &self,
        passphrase: String,
        tell_contacts: bool,
    ) -> Result<String, MobileError> {
        let passphrase = Zeroizing::new(passphrase);
        self.ask(|reply| Command::Erase {
            passphrase,
            tell: tell_contacts,
            reply,
        })
        .await
    }

    /// Whether `passphrase` is this profile's (for the app's lock screen).
    pub async fn check_passphrase(&self, passphrase: String) -> bool {
        let (reply, answer) = oneshot::channel();
        self.tell(Command::CheckPassphrase(passphrase, reply));
        answer.await.unwrap_or(false)
    }

    /// The app is on screen again after `away_secs` in the background.
    /// After a while away the connections are made again (iOS cuts them).
    pub fn foreground(&self, away_secs: u64) {
        self.tell(Command::Foreground {
            away: Duration::from_secs(away_secs),
        });
    }

    /// Try connecting now instead of waiting for the next attempt.
    pub fn retry(&self) {
        self.tell(Command::Retry);
    }

    /// Hand off anything queued and disconnect.
    pub async fn shutdown(&self) {
        let (reply, done) = oneshot::channel();
        self.tell(Command::Shutdown(reply));
        let _ = done.await;
    }
}

impl Messenger {
    /// Open or create the profile on a new thread and run the messenger's
    /// loop there, over the network `make` builds for it.
    fn start<N, F, Fut>(
        dir: PathBuf,
        passphrase: Zeroizing<String>,
        create: bool,
        vault: Arc<dyn Vault>,
        listener: Arc<dyn Listener>,
        make: impl FnOnce(&Node, Arc<Shared>) -> F + Send + 'static,
    ) -> Result<Arc<Self>, MobileError>
    where
        N: privmsg_transport::Network,
        F: FnMut() -> Fut,
        Fut: std::future::Future<Output = anyhow::Result<N>>,
    {
        init_logging();
        harden_process();
        let shared = Arc::new(Shared {
            view: Mutex::new(View::default()),
            listener,
        });
        let (commands, inbox) = unbounded_channel();
        let (ready, started) = std::sync::mpsc::channel();
        let thread_shared = shared.clone();
        std::thread::Builder::new()
            .name("privmsg".into())
            .stack_size(STACK_SIZE)
            .spawn(move || {
                let node = if create {
                    Node::create_with(&dir, &passphrase, vault)
                } else {
                    Node::open_with(&dir, &passphrase, vault)
                };
                drop(passphrase);
                let runtime = tokio::runtime::Builder::new_multi_thread()
                    .enable_all()
                    .thread_name("privmsg-worker")
                    .thread_stack_size(STACK_SIZE)
                    .build()
                    .map_err(anyhow::Error::from);
                let (mut node, runtime) = match (node, runtime) {
                    (Ok(node), Ok(runtime)) => (node, runtime),
                    (Err(e), _) | (_, Err(e)) => {
                        let _ = ready.send(Err(e));
                        return;
                    }
                };
                // Older versions kept the Nym keys in files of their own.
                if let Err(e) = runtime.block_on(node.adopt_nym_files()) {
                    let _ = ready.send(Err(e));
                    return;
                }
                {
                    // So the app has contacts and messages to show at once.
                    let mut view = thread_shared.view.lock().expect("view lock");
                    view.refresh(&node);
                    view.status = if node.settings().tor {
                        ConnectionStatus::StartingTor { percent: 0 }
                    } else {
                        ConnectionStatus::Connecting
                    };
                }
                let _ = ready.send(Ok(()));
                let network = make(&node, thread_shared.clone());
                runtime.block_on(actor::run(node, network, inbox, thread_shared));
                runtime.shutdown_timeout(Duration::from_secs(2));
            })
            .map_err(|e| anyhow!("start privmsg's thread: {e}"))?;
        started.recv().map_err(|_| stopped())??;
        Ok(Arc::new(Self { commands, shared }))
    }

    fn view(&self) -> std::sync::MutexGuard<'_, View> {
        self.shared.view.lock().expect("view lock")
    }

    fn tell(&self, cmd: Command) {
        // If the loop has stopped, the status already says so.
        let _ = self.commands.send(cmd);
    }

    async fn ask<T>(
        &self,
        cmd: impl FnOnce(oneshot::Sender<anyhow::Result<T>>) -> Command,
    ) -> Result<T, MobileError> {
        let (reply, answer) = oneshot::channel();
        self.commands.send(cmd(reply)).map_err(|_| stopped())?;
        Ok(answer.await.map_err(|_| stopped())??)
    }
}

/// The real network: Tor first (if on), then the Nym mixnet behind it.
fn nym(node: &Node, shared: Arc<Shared>) -> impl FnMut() -> NymStart {
    let (keys, tor_dir) = (node.nym_keys(), node.tor_dir());
    let (mode, tor) = (node.settings().data_mode, node.settings().tor);
    move || {
        let (keys, tor_dir, shared) = (keys.clone(), tor_dir.clone(), shared.clone());
        Box::pin(async move {
            let mut net = NymNetwork::new(keys, mode);
            if tor {
                let progress = |percent| shared.status(ConnectionStatus::StartingTor { percent });
                net = net.with_tor(start_tor(&tor_dir, progress).await?)?;
            }
            Ok(net)
        })
    }
}

type NymStart = std::pin::Pin<Box<dyn std::future::Future<Output = anyhow::Result<NymNetwork>>>>;

#[cfg(feature = "embedded-tor")]
async fn start_tor(dir: &std::path::Path, progress: impl FnMut(u8)) -> anyhow::Result<Tor> {
    Tor::start_embedded(dir, progress).await
}

/// Without the linked-in Tor (trying the library on a Mac or in the
/// simulator), the tor program named by `PRIVMSG_TOR`.
#[cfg(not(feature = "embedded-tor"))]
async fn start_tor(dir: &std::path::Path, progress: impl FnMut(u8)) -> anyhow::Result<Tor> {
    use anyhow::Context;
    Tor::start(dir, progress).await.context(
        "this test build has no Tor built in (scripts/build-ios.sh --no-tor); \
         set PRIVMSG_TOR to a tor program, or turn Tor off in Settings",
    )
}

fn init_logging() {
    static ONCE: Once = Once::new();
    ONCE.call_once(|| {
        let filter = tracing_subscriber::EnvFilter::try_from_default_env()
            .unwrap_or_else(|_| tracing_subscriber::EnvFilter::new(DEFAULT_LOG));
        let _ = tracing_subscriber::fmt()
            .with_env_filter(filter)
            .with_ansi(false)
            .with_writer(std::io::stderr)
            .try_init();
    });
}

